"""Sweep WHOLE_DEMAND_AFTER_GROWTHS with lazy_bench: best of REPS, interleaved by threshold.

usage: ae_sweep.py BIN OUT.json [thresholds...]
"""
import json
import re
import subprocess
import sys

BIN, OUT = sys.argv[1], sys.argv[2]
THRESHOLDS = [int(t) for t in sys.argv[3:]] or [3, 6, 12, 24, 48, 1000000]
ROOT = "/Users/gabe/.claude/jobs/ba6a68d6/tmp/bench-corpus"
CORPORA = {
    "mantine": "mantine/packages/@mantine/core/src",
    "chakra": "chakra-ui/packages/react/src",
    "shadcn": "shadcn-ui/apps/v4",
    "antd": "ant-design/components",
    "spectrum": "react-spectrum/packages",
}
REPS = 3
SCENARIOS = {"random50": ["--count", "50", "--seed", "1"], "all": ["--all"]}


def run(corpus, threshold, scenario):
    cmd = [
        "/usr/bin/time", "-l", BIN,
        "--src", f"{ROOT}/{CORPORA[corpus]}",
        "--cache", f"/Users/gabe/.claude/jobs/ba6a68d6/tmp/ae-cache/{corpus}",
        "--dependencies", "--full", "--whole-after", str(threshold), *SCENARIOS[scenario],
    ]
    p = subprocess.run(cmd, capture_output=True, text=True)
    line = [l for l in p.stdout.splitlines() if l.startswith("{")][-1]
    d = json.loads(line)
    rss = int(re.search(r"(\d+)\s+maximum resident set size", p.stderr).group(1)) / 1e6
    each = d["eachMs"]
    return {
        "answerMs": d["answerMs"], "startMs": d["startMs"], "slowestMs": max(each) if each else 0.0,
        "rssMB": rss, "depFiles": d["dependencyFiles"], "digest": d["digest"],
    }


results = {}
for corpus in CORPORA:
    for scenario in SCENARIOS:
        runs = {t: [] for t in THRESHOLDS}
        for _ in range(REPS):
            for t in THRESHOLDS:
                runs[t].append(run(corpus, t, scenario))
        for t in THRESHOLDS:
            r = runs[t]
            results[f"{corpus}/{scenario}/{t}"] = {
                "answerMs": min(x["answerMs"] for x in r),
                "answerMsMax": max(x["answerMs"] for x in r),
                "slowestMs": min(x["slowestMs"] for x in r),
                "rssMB": min(x["rssMB"] for x in r),
                "depFiles": r[0]["depFiles"],
                "digests": sorted({x["digest"] for x in r}),
            }
        print(corpus, scenario, "done", flush=True)
json.dump(results, open(OUT, "w"), indent=1)

for scenario in SCENARIOS:
    print(f"\n## {scenario}: answer ms (best of {REPS}) / peak RSS MB / dep files")
    print("corpus    " + "".join(f"{('never' if t >= 1000000 else t):>22}" for t in THRESHOLDS))
    for corpus in CORPORA:
        row = f"{corpus:9} "
        for t in THRESHOLDS:
            r = results[f"{corpus}/{scenario}/{t}"]
            row += f"{r['answerMs']:8.0f}/{r['rssMB']:5.0f}/{r['depFiles']:5d}  "
        print(row)

