    let cache = tempfile::TempDir::new().expect("temp cache dir");
    let options = PipelineOptions {
        src_dirs: vec![dir],
        tsconfig_path: Some(tsconfig),
        cache_dir: Some(Utf8PathBuf::from_path_buf(cache.path().to_owned()).expect("UTF-8 temp path")),
        ..Default::default()
    };

