    n = len(index) + 1
    w = [0.0] * n
    total = sum(g[1] for g in groups.values())
    prior = sum(g[0] for g in groups.values()) / total
    w[0] = math.log(prior / (1 - prior))
    m = [0.0] * n
    for _ in range(epochs):
