import json
import subprocess
from pathlib import Path

worktree = Path('/Users/gabe/Projects/caliper/.claude/worktrees/agent-a1526a7ea90ed3a95')
binary = worktree / 'target/release/caliper-docgen'
root = Path('/Users/gabe/.claude/jobs/ba6a68d6/tmp/bench-corpus')
sources = {
    'mantine': root / 'mantine/packages/@mantine/core/src',
    'chakra': root / 'chakra-ui/packages/react/src',
    'antd': root / 'ant-design/components',
    'spectrum': root / 'react-spectrum/packages',
}
for name, src in sources.items():
    result = subprocess.run(
        [str(binary), 'extract', '--src', str(src), '--json', '--html-attributes', 'full',
         '--include-unexported', '--load-dependencies', '--quiet'],
        cwd=worktree, check=True, capture_output=True,
    )
    path = Path('/private/tmp') / f'caliper-{name}-callable.json'
    path.write_bytes(result.stdout)
    old = json.loads((Path('/private/tmp/caliper-confidence-work') / f'{name}.caliper.json').read_text())
    new = json.loads(result.stdout)

    def props(document, key):
        component = document['components'][key]
        return set().union(*(document['propSets'][pid] for pid in component['props']))

    gained = {}
    lost = {}
    for key in old['components'].keys() & new['components'].keys():
        before, after = props(old, key), props(new, key)
        if after - before:
            gained[key] = len(after - before)
        if before - after:
            lost[key] = len(before - after)
    print(name, 'components', len(old['components']), len(new['components']),
          'gained', len(gained), sum(gained.values()), 'lost', len(lost), sum(lost.values()),
          'top', sorted(gained.items(), key=lambda item: -item[1])[:8], flush=True)

