                let default_value = state
                    .param_default(mapping, &field.name)
                    .map(|code| DefaultValue { value: code.value.clone(), computed: code.computed });
                chain.props.push(ctx.share(ParsedProp::new(
                    field.name.clone(),
                    prop_type,
                    field.required,
                    default_value,
                    field.description.clone(),
                    Default::default(),
                    None,
                    vec![],
                )));
            }
            chain
        }
