    export function Wrapped(props: React.ComponentProps<typeof Button>) { return null; }\n";

#[test]
fn component_props_reads_an_imported_callable_declaration() {
    let (_tmp, root) = project(&[
        (
            "node_modules/callable-kit/package.json",
