//! Function type and typeof resolution.

use camino::Utf8Path;
use compact_str::CompactString;

use crate::types::*;

use super::primitives::union_of;
use super::ResolutionContext;

/// A function type with its parameters and return type as written. A signature names its types (`(mode: CalendarMode)
/// => void`) the way TypeScript prints it; expanding each alias into its definition would read worse and, for a
/// conditional or mapped alias, would leave raw type text in place of the name.
pub(super) fn resolve_function_type(
    type_params: &[CompactString],
    params: &[CollectedType],
    param_names: &[Option<CompactString>],
    return_type: &CollectedType,
) -> PropType {
    let params = params
        .iter()
        .enumerate()
        .map(|(i, param)| FunctionParam {
            name: param_names.get(i).cloned().flatten().map(|n| n.to_string()),
            param_type: as_written(param),
        })
        .collect();
    PropType::Function {
        type_params: type_params.iter().map(|p| p.to_string()).collect(),
        params,
        return_type: Box::new(as_written(return_type)),
    }
}

/// `ct` as its source spells it: names stay names, and a form `PropType` has no shape for keeps its source text.
pub(super) fn as_written(ct: &CollectedType) -> PropType {
    let named = |name: std::string::String| PropType::Named { name: name.into(), args: vec![] };
    match ct {
        CollectedType::String => PropType::String,
        CollectedType::Number => PropType::Number,
        CollectedType::Boolean => PropType::Boolean,
        CollectedType::Null => PropType::Null,
        CollectedType::Undefined => PropType::Undefined,
        CollectedType::Any => PropType::Any,
        CollectedType::Never => PropType::Never,
        CollectedType::Unknown => PropType::Unknown,
        CollectedType::Void => PropType::Void,
        CollectedType::StringLiteral(s) => PropType::StringLiteral(s.to_string()),
        CollectedType::NumberLiteral(n) => PropType::NumberLiteral(*n),
        CollectedType::BoolLiteral(b) => PropType::BoolLiteral(*b),
        CollectedType::Union(members) => union_of(members.iter().map(as_written)),
        CollectedType::Intersection(members) => PropType::Intersection(members.iter().map(as_written).collect()),
        CollectedType::Array(inner) => PropType::Array(Box::new(as_written(inner))),
        CollectedType::Tuple(members) => PropType::Tuple(members.iter().map(as_written).collect()),
        CollectedType::Object(fields) => PropType::Object(
            fields
                .iter()
                .map(|f| ObjectField {
                    name: f.name.clone(),
                    prop_type: as_written(&f.collected_type),
                    required: f.required,
                    description: f.description.clone(),
                })
                .collect(),
        ),
        CollectedType::Named { name, args } => {
            PropType::Named { name: name.clone(), args: args.iter().map(as_written).collect() }
        }
        CollectedType::Function { type_params, params, param_names, return_type } => {
            resolve_function_type(type_params, params, param_names, return_type)
        }
        CollectedType::AtFile { inner, .. } => as_written(inner),
        CollectedType::BigInt
        | CollectedType::Symbol
        | CollectedType::TypeOf(_)
        | CollectedType::KeyOf(_)
        | CollectedType::IndexedAccess { .. }
        | CollectedType::TemplateLiteral(_)
        | CollectedType::Conditional { .. }
        | CollectedType::Mapped { .. }
        | CollectedType::Raw(_) => named(ct.to_raw_string()),
    }
}

pub(super) fn resolve_typeof(
    name: &CompactString,
    consuming_file: &Utf8Path,
    ctx: &ResolutionContext,
    diagnostics: &mut Vec<Diagnostic>,
) -> PropType {
    // `typeof X` — look for X in global.enums (for cva() results), via the
    // precomputed bare-name index (O(1) instead of a linear scan over every
    // enum/cva/tv/recipe entry in the project with a per-candidate allocation).
    super::deps::record_bare_name(name);
    let found_enum = ctx.enum_key_for(name.as_str(), consuming_file).and_then(|key| ctx.global.enums.get(key.as_str()));

    if found_enum.is_some() {
        // Has cva-like enum entries — the VariantProps<typeof X> pattern handles this.
        // At the type level, surface as Named.
        return PropType::Named { name: name.clone(), args: vec![] };
    }

    diagnostics.push(Diagnostic {
        severity: DiagnosticSeverity::Info,
        message: format!("typeof '{}' in '{}' — could not statically evaluate", name, consuming_file),
        file: Some(consuming_file.to_string()),
        line: None,
        column: None,
        help: Some(
            "Only components, cva variants and `as const` arrays have a type here. The type of a value built by a \
             call (a zod schema behind `z.infer`, a store, a hook's result) comes from the checker: declare the type \
             where it is used, or run with `--experimental-semantic-types`."
                .into(),
        ),
        code: DiagnosticCode::OpaqueType,
        affects: Vec::new(),
    });

    // The value's type, not the value: spelled as written, as TypeScript prints it.
    PropType::Named { name: format!("typeof {name}").into(), args: vec![] }
}

//! The props of a component a generic call builds, read from what the callee returns.
//!
//! `const Button = factory<ButtonFactory>(render)` is whatever `factory` returns. With the callee's type parameters
//! bound to the call's type arguments, the props parameter of the React component type in its result is the
//! component's props, as TypeScript (and react-docgen-typescript) reads them: Mantine's `factory` returns
//! `MantineComponent<Payload>`, whose props are `Payload['props']` plus `component` and `renderRoot`. The extractor's
//! choice among the type arguments (`extractor/wrapper.rs`) is the fallback for a callee with no known result. Nothing
//! here names a library; the React component types are React's own.

use std::sync::Arc;

use camino::{Utf8Path, Utf8PathBuf};

use crate::types::*;

use super::alias::resolve_base_as_chain;
use super::import::{lookup_interface, lookup_type_alias, resolve_to_canonical};
use super::substitute::{build_substitution, substitute_alias, substitute_type};
use super::ResolutionContext;

/// React types whose first type argument is a component's props.
const COMPONENT_TYPES: &[&str] = &[
    "NamedExoticComponent",
    "ForwardRefExoticComponent",
    "ExoticComponent",
    "FC",
    "FunctionComponent",
    "VFC",
    "VoidFunctionComponent",
    "ComponentType",
    "JSXElementConstructor",
];

/// Aliases followed from the result type to the component type; the bound only guards against a cycle.
const MAX_DEPTH: u8 = 8;

/// The props chain of the component a generic call builds, from its callee's result type. `None` when the callee is
/// not a project function with a known result, the result has no React component type, or its props evaluate to
/// nothing (a conditional over an unbound generic, as in Mantine's `polymorphicFactory`): the extractor's selection
/// is then the closer answer.
pub(super) fn result_chain(
    mapping: &ComponentMapping,
    ctx: &ResolutionContext,
    state: &mut ResolveState,
) -> Option<super::ResolvedChain> {
    let callee = mapping.wrapper_callee.as_ref()?;
    let (props, props_file, type_params, factory_params) = result_props(callee, &mapping.file_path, ctx, 0)?;
    let mut attempt = state.branch();
    attempt.add_type_params(type_params.iter());
    attempt.add_type_params(factory_params.iter());
    let mut chain = resolve_base_as_chain(&props, &props_file, mapping, ctx, &mut attempt, 0);
    if chain
        .composes
        .iter()
        .any(|name| factory_params.iter().any(|param| name == param.as_str() || name.starts_with(&format!("{param}["))))
    {
        let fallback = super::chain::resolve_props_chain(
            mapping.props_type_name.as_str(),
            &mapping.props_type_args,
            &mapping.file_path,
            mapping,
            ctx,
            &mut attempt,
            0,
        );
        // An explicit `any` from the selected payload absorbs the conditional's tentative type in an intersection.
        for prop in &fallback.props {
            if matches!(prop.prop_type, PropType::Any) {
                if let Some(existing) = chain.props.iter_mut().find(|existing| existing.name == prop.name) {
                    *existing = Arc::clone(prop);
                }
            }
        }
        chain.merge_parent(fallback);
    }
    if chain.props.is_empty() && chain.inheritance.is_empty() {
        return None;
    }
    state.absorb(attempt);
    Some(chain)
}

fn result_props(
    callee: &WrapperCallee,
    caller_file: &Utf8Path,
    ctx: &ResolutionContext,
    depth: u8,
) -> Option<(CollectedType, Utf8PathBuf, Vec<TypeName>, Vec<TypeName>)> {
    if depth > MAX_DEPTH {
        return None;
    }
    let mut ignored = Vec::new();
    let (file, name) = resolve_to_canonical(&callee.name, caller_file, ctx, &mut ignored)
        .unwrap_or_else(|| (caller_file.to_owned(), callee.name.to_string()));
    super::deps::record(&file);
    let function = ctx.global.function_results.get(&format!("{file}:{name}"))?;
    let bindings = build_substitution(&function.type_params, &callee.type_args, caller_file, &mut ignored);
    if let Some(inner) = &function.returned_call {
        let inner = WrapperCallee {
            name: inner.name.clone(),
            type_args: inner.type_args.iter().map(|arg| substitute_type(arg, &bindings)).collect(),
        };
        return result_props(&inner, &file, ctx, depth + 1);
    }
    let result = substitute_type(&function.result, &bindings);
    let (props, props_file, type_params) = component_props_type(&result, &file, ctx, 0)?;
    Some((props, props_file, type_params, function.type_params.clone()))
}

