        return Some((module.to_owned(), CompactString::from(name)));
    }
    // A member of a value the module declares (`Primitive.div`): its declaration is the value's.
    if name.split_once('.').is_some_and(|(head, _)| declares(&data, module, head)) {
        return Some((module.to_owned(), CompactString::from(name)));
