    &mut self,
    decl: &Binding<'_, 'a>,
    name: &str,
) -> Option<ComponentMapping> {
    let (params, shape) = match peel_expr(decl.init.as_ref()?) {
        Expression::ArrowFunctionExpression(afe) => (&*afe.params, FunctionShape::of_arrow(afe)),
        Expression::FunctionExpression(fe) => (&*fe.params, FunctionShape::of_function(fe)),
        _ => return None,
    };
    let type_ann = params.items.first()?.type_annotation.as_ref()?;
    if let Err(reason) = renders(&shape, &|n| self.may_be_react(n)) {
        self.decline_reason = Some(format!("'{name}' takes a typed props parameter but {reason}"));
        return None;
    }
    let (props_name, type_args) = self.extract_type_name_from_type(&type_ann.type_annotation)?;
    let param_defaults = self.extract_param_defaults(params);
    let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
    Some(
        ComponentMapping::new(
            name.to_owned(),
            props_name,
            self.file_path.clone(),
            decl.span.start,
            decl.span.end,
            DetectionRule::TypedFunctionExpression,
        )
        .with_props_type_args(type_args)
        .with_doc(description, tags)
        .with_param_defaults(param_defaults),
    )
}

/// Try to detect: `const Button = anyHOC(function Button(props: ButtonProps) {...})`
pub(super) fn try_hoc_wrapped<'a>(&mut self, decl: &Binding<'_, 'a>, name: &str) -> Option<ComponentMapping> {
    let init = decl.init.as_ref()?;
    let call = match peel_expr(init) {
        Expression::CallExpression(ce) => ce,
        _ => return None,
    };

    // First arg should be a function with a typed props param — or a forwardRef() call.
    let first_arg = call.arguments.first()?;

    // Handle memo(forwardRef<Ref, Props>(...)) — inner call is forwardRef
    if let Argument::CallExpression(inner) = first_arg {
        if let Some(inner_name) = self.extract_callee_name(inner) {
            if matches!(inner_name.as_str(), "forwardRef" | "React.forwardRef") {
                let type_params = inner.type_arguments.as_ref()?;
                if type_params.params.len() >= 2 {
                    let (props_name, type_args) = self.extract_type_name_from_type(&type_params.params[1])?;
                    let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
                    return Some(
                        ComponentMapping::new(
                            name.to_owned(),
                            props_name,
                            self.file_path.clone(),
                            decl.span.start,
                            decl.span.end,
                            DetectionRule::HocWrapper,
                        )
                        .with_props_type_args(type_args)
                        .with_doc(description, tags),
                    );
                }
            }
        }
        return None;
    }

    let (fn_name, params, shape) = match first_arg {
        Argument::FunctionExpression(fe) => {
            (fe.id.as_ref().map(|id| id.name.as_str()), &fe.params, FunctionShape::of_function(fe))
        }
        Argument::ArrowFunctionExpression(afe) => (None, &afe.params, FunctionShape::of_arrow(afe)),
        _ => return None,
    };

    // Rules out anonymous utility functions, which aren't components.
    if let Some(fn_name_str) = fn_name {
        if !is_pascal_case(fn_name_str) {
            return None;
        }
    }

    let first_param = params.items.first()?;
    let type_ann = first_param.type_annotation.as_ref()?;
    // `debounce((q: Row) => …)` and `createSelector((s: State) => …)` have the same shape as `memo(…)`.
    if let Err(reason) = renders(&shape, &|n| self.may_be_react(n)) {
        self.decline_reason = Some(format!("'{name}' wraps a typed function that {reason}"));
        return None;
    }
    let (props_name, type_args) = self.extract_type_name_from_type(&type_ann.type_annotation)?;

    let param_defaults = self.extract_param_defaults(params);
    let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);

    let mapping = ComponentMapping::new(
        name.to_owned(),
        props_name,
        self.file_path.clone(),
        decl.span.start,
        decl.span.end,
        DetectionRule::HocWrapper,
    )
    .with_props_type_args(type_args)
    .with_doc(description, tags)
    .with_param_defaults(param_defaults);
    // `factory<Payload>((props: P) => …)`: a generic wrapper's result type can add props, as in `wrapper.rs`.
    Some(match self.wrapper_callee(call) {
        Some(callee) => mapping.with_wrapper_callee(callee),
        None => mapping,
    })
}

/// Try to detect declared `ForwardRefExoticComponent<Props>` and `MemoExoticComponent<(props: Props) => JSX>` values.
///
/// Common in .d.ts files — no initializer, just a type annotation.
pub(super) fn try_exotic_component_decl<'a>(
    &mut self,
    decl: &VariableDeclarator<'a>,
    name: &str,
) -> Option<ComponentMapping> {
    let type_ann = decl.type_annotation.as_ref()?;
    let ct = self.ts_type_to_collected(&type_ann.type_annotation);

    let is_react_type = |name: &str, expected: &str| {
        name == expected
            || name.rsplit_once('.').is_some_and(|(prefix, suffix)| {
                suffix == expected
                    && (prefix == "React"
                        || self.data.imports.iter().any(|binding| {
                            binding.local_name == prefix
                                && binding.exported_name == "*"
                                && binding.specifier == "react"
                        }))
            })
    };
    let exotic_args = |ty: &crate::types::CollectedType| match ty {
        crate::types::CollectedType::Named { name, args } if is_react_type(name, "ForwardRefExoticComponent") => {
            Some((args.clone(), false))
        }

//! React builtin type mapping and related helpers.

use camino::Utf8Path;
use oxc_resolver::Resolver;

use crate::types::*;

use super::collected::resolve_collected_type;
use super::ResolutionContext;

/// Map a React builtin type name to the appropriate `PropType`.
pub(super) fn react_type_to_prop_type(
    name: &str,
    args: &[CollectedType],
    consuming_file: &Utf8Path,
    ctx: &ResolutionContext,
    state: &mut ResolveState,
    depth: u8,
) -> PropType {
    // Strip "React." prefix for matching.
    let strip = name.strip_prefix("React.").unwrap_or(name);

    match strip {
        // React node types.
        "ReactNode" | "ReactElement" | "JSX.Element" | "ReactPortal" | "ReactFragment" | "ReactChild" => {
            PropType::ReactNode
        }

        // CSS properties.
        "CSSProperties" | "CSSObject" => PropType::CssProperties,

        // Ref types.
        "Ref" | "RefObject" | "ForwardedRef" | "MutableRefObject" | "RefCallback" | "LegacyRef" => {
            let element = args.first().map(|a| a.to_raw_string());
            PropType::Ref { element }
        }

        // ElementType — component-as-prop.
        "ElementType" => PropType::ElementType,

        // FC / FunctionComponent — return as Named.
        "FC"
        | "FunctionComponent"
        | "VFC"
        | "VoidFunctionComponent"
        | "ComponentType"
        | "ForwardRefExoticComponent" => {
            let resolved_args: Vec<PropType> =
                args.iter().map(|a| resolve_collected_type(a, consuming_file, ctx, state, depth + 1)).collect();
            PropType::Named { name: name.into(), args: resolved_args }
        }

        // ComponentPropsWithoutRef<'button'> or ComponentPropsWithoutRef<typeof X>.
        "ComponentPropsWithoutRef" | "ComponentProps" | "ComponentPropsWithRef" => {
            if let Some(first) = args.first() {
                match first {
                    CollectedType::StringLiteral(el) => {
                        PropType::HtmlAttributes { element: el.to_lowercase().to_string(), omitted: vec![] }
                    }
                    other => PropType::Named {
                        name: name.into(),
                        args: vec![resolve_collected_type(other, consuming_file, ctx, state, depth + 1)],
                    },
                }
            } else {
                PropType::Any
            }
        }

        // PropsWithChildren / PropsWithRef — resolve inner type.
        "PropsWithChildren" | "PropsWithRef" => {
            if let Some(first) = args.first() {
                resolve_collected_type(first, consuming_file, ctx, state, depth + 1)
            } else {
                PropType::Any
            }
        }

        // ElementRef.
        "ElementRef" => PropType::Ref { element: None },

        // Context / Consumer / Provider — surface as Named.
        "Context" | "Consumer" | "Provider" | "RefAttributes" => {
            let resolved_args: Vec<PropType> =
                args.iter().map(|a| resolve_collected_type(a, consuming_file, ctx, state, depth + 1)).collect();
            PropType::Named { name: name.into(), args: resolved_args }
        }

        // Default — surface as Named with resolved args.
        _ => {
            let resolved_args: Vec<PropType> =
                args.iter().map(|a| resolve_collected_type(a, consuming_file, ctx, state, depth + 1)).collect();
            PropType::Named { name: name.into(), args: resolved_args }
        }
    }
}

/// Best-effort path to the @types/react .d.ts file for RDT propFilter compat.
/// Falls back to a synthetic path if @types/react is not installed.
pub(super) fn resolve_react_types_file(from_file: &Utf8Path, ctx: &ResolutionContext) -> String {
    let dir = from_file.parent().map_or("", Utf8Path::as_str);
    if let Some(found) = ctx.react_types_files.get(dir) {
        return found.clone();
    }
    let found = resolve_package_types_file(&ctx.oxc_resolver, &ctx.types_first_resolver, from_file, "react")
        .unwrap_or_else(|| "node_modules/@types/react/index.d.ts".to_owned());
    ctx.react_types_files.insert(Box::from(dir), found.clone());
    found
}

/// Resolve `package_name` to its declaration file the way TypeScript does. `oxc_resolver`'s `resolve_dts` stops at the
/// first `exports` key that matches any condition, even one pointing at JavaScript, so two retries follow: with only
/// the `types` conditions (`types_first`), for a package that lists `"import"` before `"types"`; then the separate
/// `@types/<name>` package, for one with no types of its own. A declaration file that doesn't exist counts as none.
pub(super) fn resolve_package_types_file(
    resolver: &Resolver,
    types_first: &Resolver,
    importing_file: &Utf8Path,
    package_name: &str,
) -> Option<String> {
    let declaration = |resolver: &Resolver, specifier: &str| {
        let resolved = resolver.resolve_dts(importing_file.as_std_path(), specifier).ok()?;
        // `resolve_dts` returns an `exports` target without checking it exists (an unbuilt workspace package's `dist`).
        let is_declaration =
            [".d.ts", ".d.mts", ".d.cts"].iter().any(|ext| resolved.path().to_string_lossy().ends_with(ext));
        (is_declaration && resolved.path().is_file()).then(|| resolved.path().to_string_lossy().into_owned())
    };
    declaration(resolver, package_name)
        .or_else(|| declaration(types_first, package_name))
        .or_else(|| declaration(resolver, &format!("@types/{}", mangle_scoped_package_name(package_name))))

