fn publish(snapshot: &ExtractionOutput, out: Option<&str>, exit_code: &AtomicI32) {
    exit_code.store(watch_exit_code(snapshot), Ordering::Relaxed);
    if let Some(failure) = out.and_then(|out| write_snapshot(out, snapshot)) {
