            path.read_dir_utf8().ok()?.flatten().map(|entry| entry.file_name().to_owned()).collect();
        names.sort();
        names.hash(&mut hasher);
    } else {
        std::fs::read(path).ok()?.hash(&mut hasher);
    }
    Some(hasher.finish())
