//! Import resolution map — built from `GlobalSourceData`, used read-only during resolution.
//!
//! Answers the question: "in file F, the name N was imported — what specifier and
//! canonical name does it refer to?"  Actual path resolution (specifier → absolute
//! path) is left to the caller via `oxc_resolver`.

use camino::Utf8Path;
use compact_str::CompactString;
use rustc_hash::FxHashMap;

use crate::path_key::PathKey;
use crate::types::{GlobalSourceData, LexedExport};

// ─── Public Types ─────────────────────────────────────────────────────────────

/// Where an imported name comes from, as written in the source.
#[derive(Debug, Clone)]
pub struct ImportRef {
    /// The import specifier as written: `"@radix-ui/react-button"`, `"./types"`, etc.
    pub specifier: String,
    /// The exported name in the source module (original name before `as` rename).
    pub exported_name: CompactString,
    /// `true` for `import type { ... }` bindings.
    #[allow(dead_code)]
    pub is_type_only: bool,
}

/// Result of walking one step of a re-export chain.
#[derive(Debug, Clone)]
pub enum ReExportStep {
    /// Found a named re-export — caller resolves `source_specifier` to a file and recurses.
    Named { source_specifier: String, source_name: String },
    /// Found one or more `export * from "..."` entries — caller checks each.
    Wildcards(Vec<String>),
}

// ─── ImportResolutionMap ──────────────────────────────────────────────────────

/// Maps `(consuming_file, local_name)` → import reference.
/// Built once from `GlobalSourceData`, then used read-only during parallel resolution.
pub struct ImportResolutionMap {
    /// `file_path` → (`local_name` → specifier + original exported name).
    /// Nested (rather than a flat `(Utf8PathBuf, CompactString)` key) so lookups can
    /// borrow `&Utf8Path` directly instead of cloning the whole path per call.
    /// Note: we store the specifier string, not the resolved file path.
    /// The resolver calls `oxc_resolver` to turn specifiers into absolute paths.
    bindings: FxHashMap<PathKey, FxHashMap<CompactString, ImportRef>>,
    /// `global.re_export_map`, keyed for string-hashed lookups during barrel walks.
    re_exports: FxHashMap<PathKey, Vec<LexedExport>>,
    /// Loaded dependency files' imports and re-exports (ADR 0010), consulted for a file this map holds nothing for.
    pub(crate) fallback: Option<std::sync::Arc<ImportResolutionMap>>,
}

impl ImportResolutionMap {
    /// Build from a fully-merged `GlobalSourceData`.
    /// Called once per extraction run, before parallel resolution starts.
    ///
    /// No I/O — pure data transformation.
    pub fn build(global: &GlobalSourceData) -> Self {
        let mut bindings: FxHashMap<PathKey, FxHashMap<CompactString, ImportRef>> = FxHashMap::default();

        for (file_path, import_bindings) in &global.import_map {
            let per_file = bindings.entry(PathKey::from(file_path.as_path())).or_default();
            for binding in import_bindings {
                per_file.insert(
                    binding.local_name.clone(),
                    ImportRef {
                        specifier: binding.specifier.clone(),
                        exported_name: binding.exported_name.clone(),
                        is_type_only: binding.is_type_only,
                    },
                );
            }
        }

        let re_exports = global
            .re_export_map
            .iter()
            .map(|(file_path, exports)| (PathKey::from(file_path.as_path()), exports.clone()))
            .collect();
        Self { bindings, re_exports, fallback: None }
    }

    /// Given a file and a local name used in that file, return where it was imported from.
    ///
    /// Returns `None` if the name is locally defined (not imported).
    pub fn find_import(&self, file: &Utf8Path, local_name: &str) -> Option<&ImportRef> {
        match self.bindings.get(file.as_str()) {
            Some(per_file) => per_file.get(local_name),
            None => self.fallback.as_ref()?.find_import(file, local_name),
        }
    }

    /// The local name of the declaration `file` itself exports as `name` (`export function f`, `export { g as f }`),
    /// whatever kind of declaration it is.
    pub fn local_export(&self, file: &Utf8Path, name: &str) -> Option<String> {
        let Some(exports) = self.re_exports.get(file.as_str()) else {
            return self.fallback.as_ref()?.local_export(file, name);
        };
        exports.iter().find_map(|export| match export {
            LexedExport::LocalDeclaration { name: exported, declared_as, .. } if exported == name => {
                Some(declared_as.clone().unwrap_or_else(|| exported.clone()))
            }
            _ => None,
        })
    }

    /// Walk one step of the re-export chain for `barrel_file`.
    ///
    /// - If a `ReExportNamed` entry matches `exported_name`, returns `Named { .. }`.
    /// - A member of a re-exported namespace (`Menu.Root` where the barrel has `export * as Menu from "./menu"`)
    ///   returns `Named` for the member in the namespace's module.
    /// - If no named match is found but there are `ReExportAll` entries, returns `Wildcards(..)`.
    /// - Returns `None` if the barrel file has no relevant re-exports.
    pub fn resolve_reexport_chain(&self, barrel_file: &Utf8Path, exported_name: &str) -> Option<ReExportStep> {
        let Some(exports) = self.re_exports.get(barrel_file.as_str()) else {
            return self.fallback.as_ref()?.resolve_reexport_chain(barrel_file, exported_name);
        };
        let namespace_member = exported_name.split_once('.');

        let mut wildcard_specifiers: Vec<String> = Vec::new();

        for export in exports {
            match export {
                LexedExport::ReExportNamed { local_name, source_name, source_specifier, .. } => {
                    if local_name == exported_name {
                        return Some(ReExportStep::Named {
                            source_specifier: source_specifier.clone(),
                            source_name: source_name.clone(),
                        });
                    }
                }
                LexedExport::ReExportNamespace { namespace, source_specifier } => {
                    if let Some((_, member)) = namespace_member.filter(|(prefix, _)| prefix == namespace) {
                        return Some(ReExportStep::Named {
                            source_specifier: source_specifier.clone(),
                            source_name: member.to_owned(),
                        });
                    }
                }

    }
}

impl EnumValue {
    /// Render as the string a `LiteralUnion` member expects — every variant
    /// display-formatted, regardless of its original JS type.
    pub fn to_display_string(&self) -> std::string::String {
        match self {
            EnumValue::String(s) => s.clone(),
            EnumValue::Number(n) => n.to_string(),
            EnumValue::Bool(b) => b.to_string(),
            EnumValue::Spread { spread } => format!("...{spread}"),
        }
    }
}

// ─── Source Data (collected during Phase 0-2) ─────────────────────────────────

/// Raw data collected from parsing a single file.
/// Owned data only — no AST references. Safe for rayon + arc.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct SourceData {
    /// Interfaces found in this file.
    /// Key: "${absolute_file_path}:${interface_name}"
    pub interfaces: FxHashMap<std::string::String, CollectedInterface>,

    /// Type aliases found in this file.
    /// Key: "${absolute_file_path}:${type_name}"
    pub type_aliases: FxHashMap<std::string::String, CollectedTypeAlias>,

    /// Declared type parameter names for generic type alias declarations, e.g.
    /// `type Assign<T, U> = ...` records `["T", "U"]` here. Keyed identically to
    /// `type_aliases`. Absent (no entry) for the common non-generic alias — the
    /// resolver only attempts call-site substitution when an entry exists.
    pub type_alias_params: FxHashMap<std::string::String, Vec<TypeName>>,

    /// Declared type parameter names for generic interface declarations, e.g.
    /// `interface ColumnDef<TData, TValue> { ... }` records `["TData", "TValue"]`
    /// here. Keyed identically to `interfaces`. Used by the resolver to recognize
    /// a bare `TData` reference inside the interface's own body as an expected
    /// generic placeholder rather than an unresolvable type — see
    /// `resolver::chain::resolve_interface_chain`.
    pub interface_type_params: FxHashMap<std::string::String, Vec<TypeName>>,

    /// Enum-like values found in this file.
    /// Key: "${absolute_file_path}:${name}"
    pub enums: FxHashMap<std::string::String, Vec<EnumEntry>>,

    /// Flat `const X = [...] as const` array literals found in this file —
    /// e.g. `const _ButtonTypes = ['default', 'primary'] as const`, referenced
    /// via `(typeof _ButtonTypes)[number]` to build a literal union without an
    /// explicit `enum`. Deliberately separate from `enums`: unlike an enum or
    /// a cva/tv variant group, a plain array has no per-entry name to group
    /// by, and `enums` is surfaced directly in the public `ExtractionOutput`
    /// (see `pipeline::collect_public_enums`) — these arrays are resolver-
    /// internal only, never part of that output.
    /// Key: "${absolute_file_path}:${name}"
    pub const_arrays: FxHashMap<std::string::String, Vec<EnumValue>>,

    /// Component → prop type mappings found in this file.
    /// Only populated for .tsx files.
    pub component_mappings: Vec<ComponentMapping>,

    /// Import bindings in this file — local name → source
    pub imports: Vec<ImportBinding>,

    /// Re-exports from this file
    pub exports: Vec<LexedExport>,

    /// Non-fatal issues discovered while parsing this file (e.g. excessive nesting,
    /// TypeScript syntax errors). Drained into the pipeline's top-level diagnostics
    /// during `GlobalSourceData` merge — never dropped silently.
    pub diagnostics: Vec<Diagnostic>,

    /// What each generic function declared in this file returns (see [`FunctionResult`]).
    /// Key: "${absolute_file_path}:${name}"
    pub function_results: FxHashMap<std::string::String, FunctionResult>,

    /// Each declared type parameter's default (`interface DOMAttributes<T = FocusableElement>`), in declaration order,
    /// for the generic aliases and interfaces that declare at least one. Keyed as `type_alias_params` and
    /// `interface_type_params`; a reference that omits trailing arguments takes these, as TypeScript does.
    pub type_param_defaults: FxHashMap<std::string::String, Vec<Option<CollectedType>>>,
}

/// What a generic function returns: its declared or asserted type, or a generic call stored in a returned local const.
/// The wrapper call's type arguments bind to `type_params` before its result is resolved.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FunctionResult {
    pub type_params: Vec<TypeName>,
    pub result: CollectedType,
    /// A generic call assigned to a local const and returned by name, when there is no explicit result type.
    }
}

// ─── GlobalSourceData ─────────────────────────────────────────────────────────

/// Merged source data from all files — the shared resolution context.
/// Built once, then read by all parallel resolution workers.
/// Uses Arc in pipeline — clone is cheap.
#[derive(Debug, Default, Clone)]
pub struct GlobalSourceData {
    /// All interfaces across all files.
    /// Key: "${absolute_file_path}:${name}" — always scoped, never bare
    pub interfaces: FxHashMap<String, CollectedInterface>,

    /// All type aliases across all files.
    /// Key: "${absolute_file_path}:${name}"
    pub type_aliases: FxHashMap<String, CollectedTypeAlias>,

    /// Declared type parameter names for generic type alias declarations — see
    /// `SourceData::type_alias_params`. Key: "${absolute_file_path}:${name}"
    pub type_alias_params: FxHashMap<String, Vec<TypeName>>,

    /// Declared type parameter names for generic interface declarations — see
    /// `SourceData::interface_type_params`. Key: "${absolute_file_path}:${name}"
    pub interface_type_params: FxHashMap<String, Vec<TypeName>>,

    /// All enum-like definitions across all files.
    /// Key: "${absolute_file_path}:${name}"
    pub enums: FxHashMap<String, Vec<EnumEntry>>,

    /// All `const X = [...] as const` array literals across all files — see
    /// `SourceData::const_arrays`. Key: "${absolute_file_path}:${name}"
    pub const_arrays: FxHashMap<String, Vec<EnumValue>>,

    /// Import resolution map: file → [ImportBinding]
    pub import_map: FxHashMap<Utf8PathBuf, Vec<ImportBinding>>,

    /// Re-export map: file → [LexedExport]
    pub re_export_map: FxHashMap<Utf8PathBuf, Vec<LexedExport>>,

    /// All component mappings discovered
    pub component_mappings: Vec<ComponentMapping>,

    /// Generic functions' result types across all files — see `SourceData::function_results`.
    /// Key: "${absolute_file_path}:${name}"
    pub function_results: FxHashMap<String, FunctionResult>,

    /// Type parameter defaults across all files — see `SourceData::type_param_defaults`.
    /// Key: "${absolute_file_path}:${name}"
    pub type_param_defaults: FxHashMap<String, Vec<Option<CollectedType>>>,
}

impl GlobalSourceData {
    /// Merge a single file's SourceData into the global data.
    pub fn merge(&mut self, file_path: &Utf8Path, data: SourceData) {
        for (key, iface) in data.interfaces {
            match self.interfaces.entry(key) {
                std::collections::hash_map::Entry::Occupied(mut e) => {
                    // Declaration merging: combine props and extends
                    let existing = e.get_mut();
                    existing.props.extend(iface.props);
                    existing.extends.extend(iface.extends);
                }
                std::collections::hash_map::Entry::Vacant(e) => {
                    e.insert(iface);
                }
            }
        }
        self.type_aliases.extend(data.type_aliases);
        self.type_alias_params.extend(data.type_alias_params);
        self.interface_type_params.extend(data.interface_type_params);
        self.enums.extend(data.enums);
        self.const_arrays.extend(data.const_arrays);
        self.function_results.extend(data.function_results);
        self.type_param_defaults.extend(data.type_param_defaults);
        self.import_map.insert(file_path.to_owned(), data.imports);
        self.re_export_map.insert(file_path.to_owned(), data.exports);
        self.component_mappings.extend(data.component_mappings);
    }

    /// Remove all entries contributed by `file_path`. Called before re-merging an updated file.
    pub fn remove_file(&mut self, file_path: &Utf8Path) {
        let prefix = format!("{}:", file_path);
        self.interfaces.retain(|k, _| !k.starts_with(&prefix));
        self.type_aliases.retain(|k, _| !k.starts_with(&prefix));
        self.type_alias_params.retain(|k, _| !k.starts_with(&prefix));
        self.interface_type_params.retain(|k, _| !k.starts_with(&prefix));
        self.enums.retain(|k, _| !k.starts_with(&prefix));
        self.const_arrays.retain(|k, _| !k.starts_with(&prefix));
        self.function_results.retain(|k, _| !k.starts_with(&prefix));
        self.type_param_defaults.retain(|k, _| !k.starts_with(&prefix));
        self.import_map.remove(file_path);
        self.re_export_map.remove(file_path);
        self.component_mappings.retain(|m| m.file_path != file_path);
    }
}

