+fn shared_inline_keys(
+    left: &CollectedType,
+    right: &CollectedType,
+    file: &Utf8Path,
+    ctx: &ResolutionContext,
+) -> FxHashSet<String> {
+    fn collect(ty: &CollectedType, file: &Utf8Path, ctx: &ResolutionContext, depth: u8, keys: &mut FxHashSet<String>) {
